// STEP 1+2: validate the raw sensor message and convert it to the common JSON format
const stats = flow.get('stats') || {raw: 0, valid: 0, dropped: 0, windows: 0, summaries: 0, alerts: 0, twinUpdates: 0};
stats.raw++;
flow.set('stats', stats);

function drop(why) {
    stats.dropped++;
    flow.set('stats', stats);
    node.status({fill: 'red', shape: 'ring', text: 'dropped: ' + why});
    return null;
}

let d;
try { d = JSON.parse(msg.payload); } catch (e) { return drop('broken JSON'); }
if (!d || typeof d !== 'object') return drop('not a JSON object');
const room = msg.topic.split('/')[1];          // library/<room>/telemetry

// conversion: vendor B sends Fahrenheit -> Celsius
let temperature = d.temperature;
if (d.temperature_f !== undefined) {
    temperature = typeof d.temperature_f === 'number' ? (d.temperature_f - 32) * 5 / 9 : NaN;
}

// cleaning: missing, non-numeric or impossible values
const isNum = v => typeof v === 'number' && isFinite(v);
if (!isNum(d.occupancy) || !isNum(temperature) || !isNum(d.humidity)) return drop('missing / non-numeric value');
if (d.occupancy < 0 || d.occupancy > 500) return drop('impossible occupancy ' + d.occupancy);
if (temperature < -10 || temperature > 50) return drop('impossible temperature ' + temperature.toFixed(1));
if (d.humidity < 0 || d.humidity > 100) return drop('impossible humidity ' + d.humidity);

// conversion: equipment codes 0/1/2 -> OFF/ON/FAULT
const CODES = {0: 'OFF', 1: 'ON', 2: 'FAULT'};
const devices = {};
for (const [k, v] of Object.entries(d.equipment || {})) {
    const s = typeof v === 'number' ? CODES[v] : String(v).toUpperCase();
    if (!['OFF', 'ON', 'FAULT'].includes(s)) return drop('unknown equipment state');
    devices[k] = s;
}
const faults = Object.keys(devices).filter(k => devices[k] === 'FAULT');

stats.valid++;
flow.set('stats', stats);
msg.payload = {
    room: room,
    occupancy: d.occupancy,
    temperature: Math.round(temperature * 10) / 10,
    humidity: d.humidity,
    equipment: faults.length ? 'FAULT' : 'OK',
    devices: devices,
    faults: faults
};
node.status({fill: 'green', shape: 'dot', text: 'ok ' + room});
return msg;

// STEP 3-5: collect 10 valid readings per room, extract features, classify the room
const ROOMS = {
    R01: {name: 'Reading Hall', capacity: 80},
    R02: {name: 'Computer Lab', capacity: 40},
    R03: {name: 'Discussion Room', capacity: 12}
};
const WINDOW = 10;
const r = msg.payload;
const room = ROOMS[r.room];
if (!room) return null;

const buffers = context.get('buffers') || {};
const buf = (buffers[r.room] || []).concat([r]);
buffers[r.room] = buf.length >= WINDOW ? [] : buf;
context.set('buffers', buffers);
node.status({text: Object.keys(ROOMS).map(k => k + ' ' + (buffers[k] || []).length + '/' + WINDOW).join('  ')});
if (buf.length < WINDOW) return null;

// --- window statistics ---
const avg = a => a.reduce((s, x) => s + x, 0) / a.length;
const r1 = x => Math.round(x * 10) / 10;
const occ = buf.map(x => x.occupancy);
const avgOcc = r1(avg(occ));
const peakOcc = Math.max(...occ);
const pct = r1(avgOcc / room.capacity * 100);
const avgTemp = r1(avg(buf.map(x => x.temperature)));
const avgHum = r1(avg(buf.map(x => x.humidity)));
const last = buf[buf.length - 1];
const faults = last.faults;                     // equipment health = devices in FAULT now

// --- abnormal count: readings in the window that break a threshold rule ---
const tempBad = t => t < 20 || t > 26;
const humBad = h => h < 40 || h > 60;
const abnormal = buf.filter(x => tempBad(x.temperature) || humBad(x.humidity) ||
    x.occupancy >= 0.8 * room.capacity || x.faults.length > 0).length;

// --- rule based status ---
let status = 'NORMAL';
const reasons = [];
if (pct > 100) reasons.push('over capacity (' + pct + '%)');
if (faults.length) reasons.push('equipment FAULT: ' + faults.join(', '));
if (tempBad(avgTemp) && humBad(avgHum)) reasons.push('bad environment: ' + avgTemp + ' C and ' + avgHum + ' %');
if (reasons.length) {
    status = 'CRITICAL';
} else {
    if (tempBad(avgTemp)) reasons.push('temperature ' + avgTemp + ' C outside 20-26');
    if (humBad(avgHum)) reasons.push('humidity ' + avgHum + ' % outside 40-60');
    if (pct >= 80) reasons.push('occupancy ' + pct + '% of capacity');
    if (reasons.length) status = 'WARNING';
}

// --- occupancy trend: rising over the last 4 windows and above 70 % -> LIMITED ---
const hist = context.get('history') || {};
const h = (hist[r.room] || []).concat([avgOcc]).slice(-4);
hist[r.room] = h;
context.set('history', hist);
const rising = h.length === 4 && h.every((v, i) => i === 0 || v > h[i - 1]);
let seats = 'AVAILABLE';
if (pct >= 100) seats = 'FULL';
else if (rising && pct > 70) seats = 'LIMITED';

const stats = flow.get('stats');
stats.windows++;
flow.set('stats', stats);

msg.payload = {
    room: r.room,
    name: room.name,
    status: status,
    reasons: reasons,
    occupancy: {average: avgOcc, peak: peakOcc, percent: pct, capacity: room.capacity, trend: rising ? 'RISING' : 'STABLE'},
    environment: {temperature: avgTemp, humidity: avgHum},
    equipment: Object.assign({}, last.devices, {state: last.equipment, faults: faults.length}),
    abnormalCount: abnormal,
    seatAvailability: seats,
    windowSize: WINDOW,
    time: new Date().toISOString()
};
node.status({fill: status === 'NORMAL' ? 'green' : status === 'WARNING' ? 'yellow' : 'red',
             shape: 'dot', text: r.room + ': ' + status});
return msg;

// Alert path: CRITICAL -> immediate alert (MQTT + dashboard popup + alert list)
const s = flow.get('stats'); s.alerts++; flow.set('stats', s);
const p = msg.payload;
const version = env.get('GATEWAY_VERSION') || 'v1';
const alert = {type: 'ALERT', room: p.room, name: p.name, reasons: p.reasons,
               time: p.time, gatewayVersion: version};

// Version 2 feature: tell the staff what to do
if (version !== 'v1') {
    const r = p.reasons.join(' ');
    alert.action = r.includes('over capacity') ? 'Send students to another room'
                 : r.includes('FAULT') ? 'Call technician for: ' + r.split('FAULT: ')[1]
                 : 'Check the air conditioning / ventilation';
}

const list = flow.get('alertList') || [];
list.unshift(Object.assign({clock: new Date().toLocaleTimeString()}, alert));
flow.set('alertList', list.slice(0, 8));

const text = p.room + ' ' + p.name + ': ' + p.reasons.join('; ') + (alert.action ? ' -> ' + alert.action : '');
return [
    {topic: 'library/alerts', payload: alert},
    {topic: 'CRITICAL ALERT', payload: text},
    {payload: flow.get('alertList')}
];

// Summary path: NORMAL / WARNING -> one small summary message per window
const s = flow.get('stats'); s.summaries++; flow.set('stats', s);
const p = msg.payload;
msg.topic = 'library/' + p.room + '/summary';
msg.payload = {room: p.room, status: p.status, reasons: p.reasons, occupancy: p.occupancy.average,
               percent: p.occupancy.percent, temperature: p.environment.temperature,
               humidity: p.environment.humidity, seats: p.seatAvailability, time: p.time};
return msg;

// STEP 7: update the room twin in Ditto (REST, JSON merge-patch)
const p = msg.payload;
msg.method = 'PATCH';
msg.url = env.get('DITTO_URL') + '/api/2/things/library:' + p.room;
msg.headers = {'Content-Type': 'application/merge-patch+json', 'Authorization': 'Basic ZGl0dG86ZGl0dG8='};
msg.payload = {features: {
    occupancy:   {properties: p.occupancy},
    environment: {properties: p.environment},
    equipment:   {properties: p.equipment},
    status:      {properties: {value: p.status, reasons: p.reasons, abnormalCount: p.abnormalCount,
                               windowSize: p.windowSize, updated: p.time}},
    SeatAvailability: {properties: {value: p.seatAvailability}}
}};
return msg;

if (msg.statusCode === 204 || msg.statusCode === 200) {
    const s = flow.get('stats'); s.twinUpdates++; flow.set('stats', s);
    node.status({fill: 'green', shape: 'dot', text: 'twin updated (' + msg.url.split(':').pop() + ')'});
} else {
    node.status({fill: 'red', shape: 'ring', text: 'Ditto error ' + msg.statusCode});
    node.warn('Ditto update failed: ' + msg.statusCode + ' ' + JSON.stringify(msg.payload));
}
return null;

// STEP 10: raw vs forwarded messages (edge data reduction)
const s = flow.get('stats') || {raw: 0, valid: 0, dropped: 0, windows: 0, summaries: 0, alerts: 0, twinUpdates: 0};
const forwarded = s.summaries + s.alerts;
const reduction = s.raw ? Math.round(1000 * (1 - forwarded / s.raw)) / 10 : 0;
const data = Object.assign({}, s, {forwarded: forwarded, reductionPercent: reduction,
                                   version: env.get('GATEWAY_VERSION') || 'v1',
                                   updated: new Date().toISOString()});
const toDitto = {
    method: 'PATCH',
    url: env.get('DITTO_URL') + '/api/2/things/library:gateway',
    headers: {'Content-Type': 'application/merge-patch+json', 'Authorization': 'Basic ZGl0dG86ZGl0dG8='},
    payload: {features: {stats: {properties: data}}}
};
return [toDitto, {payload: data}];

// STEP 8: dashboard reads the room twins back from Ditto
msg.method = 'GET';
msg.url = env.get('DITTO_URL') + '/api/2/things?ids=library:R01,library:R02,library:R03';
msg.headers = {'Authorization': 'Basic ZGl0dG86ZGl0dG8='};
return msg;

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    msg.payload = {error: 'Ditto not reachable (' + msg.statusCode + ')', rooms: []};
    return msg;
}
const P = (t, f) => (t.features && t.features[f] && t.features[f].properties) || {};
const rooms = msg.payload.map(t => {
    const o = P(t, 'occupancy'), e = P(t, 'environment'), q = P(t, 'equipment'), s = P(t, 'status');
    return {
        id: t.attributes.roomId, name: t.attributes.name, floor: t.attributes.floor,
        capacity: t.attributes.capacity, serial: t.attributes.sensorSerial,
        status: s.value || 'WAITING', reasons: (s.reasons || []).join('; '),
        occ: o.average, peak: o.peak, pct: o.percent, bar: Math.min(o.percent || 0, 100), trend: o.trend,
        temp: e.temperature, hum: e.humidity, abnormal: s.abnormalCount,
        devices: ['lights', 'ac', 'computers', 'printer'].map(k => ({k: k, v: q[k] || '-'})),
        seats: P(t, 'SeatAvailability').value || '-',
        updated: s.updated ? new Date(s.updated).toLocaleTimeString() : '-'
    };
}).sort((a, b) => a.id < b.id ? -1 : 1);
msg.payload = {rooms: rooms, version: env.get('GATEWAY_VERSION') || 'v1'};
return msg;
